H.background();
const cx = H.W * 0.40, cy = H.H * 0.56;
const m = P.m, r = P.r;
const I = m * r * r;                       // I = m r^2 for a point mass
const scale = 38;                          // px per metre
const Rpx = r * scale;
const ang = t * 1.2;                        // steady rotation (bounded, loops)
// axis of rotation
H.circle(cx, cy, 6, { fill: H.colors.axis });
H.line(cx, cy - Rpx - 30, cx, cy + Rpx + 30, { color: H.colors.grid, width: 1, dash: [4, 4] });
// rod from axis to the point mass
const mx = cx + Rpx * Math.cos(ang), my = cy - Rpx * Math.sin(ang);
H.line(cx, cy, mx, my, { color: H.colors.accent, width: 3 });
// the point mass — radius scaled by sqrt(m) so area ~ m
const rad = 6 + 5 * Math.sqrt(Math.max(0.1, m));
H.circle(mx, my, rad, { fill: H.colors.warn });
// faint circle showing the orbit radius
H.circle(cx, cy, Rpx, { stroke: H.colors.grid, width: 1 });
// I shown as a proportional bar at lower-left
const bx = 28, by = H.H - 40, bw = H.clamp(I * 9, 2, H.W - 60);
H.rect(bx, by, bw, 16, { fill: H.colors.good, radius: 4 });
H.text("I", bx, by - 6, { color: H.colors.sub, size: 12 });
H.text("Moment of inertia:  I = m * r^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m.toFixed(2) + " kg   r = " + r.toFixed(2) + " m   I = " + I.toFixed(3) + " kg·m²", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "rod (radius r)", color: H.colors.accent }, { label: "mass m", color: H.colors.warn }, { label: "I (resistance to spin)", color: H.colors.good }], H.W - 230, 28);
